/* Trap Map data: the mistake behind each wrong option of the free TMUA questions.
   HU_TRAPS[id] = {reviewed, opts: {letter: {trap, why, working}}}. Students only see questions with
   reviewed: true. "working" is the calculation that turns the mistake into that option; it is for review
   and never shown to students. Edit through traps-admin.html or tools/traps-tool.js, which write this format. */
window.HU_TRAP_TYPES={
"neg-root":{"name":"Dropped a negative root","d":"Taking only the positive square root, or losing the negative solution of an equation."},
"nec-suff":{"name":"Confused necessary with sufficient","d":"Treating a condition that must hold as one that guarantees the result, or the other way round."},
"quantifier":{"name":"Negated a quantifier wrongly","d":"Negating 'for all' or 'there exists' without swapping one for the other."},
"converse":{"name":"Assumed the converse","d":"Using 'if Q then P' when only 'if P then Q' is known."},
"contrapositive":{"name":"Confused converse and contrapositive","d":"Mixing up 'if not Q then not P', which is equivalent, with 'if Q then P', which is not."},
"vacuous":{"name":"Missed a vacuous truth","d":"Forgetting that a statement about every member of an empty set is true."},
"and-or":{"name":"Confused \"and\" with \"or\"","d":"Reading a joint condition as either-or, or the reverse."},
"transform-sign":{"name":"Sign error on a transformation","d":"Shifting or reflecting a graph the wrong way, such as f(x + a) moving right."},
"sign-slip":{"name":"Sign slip in algebra","d":"A lost or extra minus sign in the working."},
"ineq-flip":{"name":"Did not reverse an inequality","d":"Multiplying or dividing an inequality by a negative number without reversing it."},
"domain":{"name":"Forgot the domain","d":"Using values that the question or a substitution rules out."},
"div-zero":{"name":"Divided by something that could be zero","d":"Cancelling a factor that may be zero and losing a solution."},
"false-root":{"name":"Kept a false root from squaring","d":"Squaring both sides and not checking the solutions in the original equation."},
"log-index":{"name":"Misused a log or index law","d":"Rules such as log(a + b) = log a + log b that do not hold."},
"trig-range":{"name":"Missed solutions in the full trig range","d":"Stopping at the principal value instead of finding every solution in the interval."},
"ordered":{"name":"Counted ordered instead of unordered","d":"Counting arrangements when only selections matter, or the reverse."},
"double-count":{"name":"Counted a case twice","d":"Including the same object in two cases that overlap."},
"missed-case":{"name":"Missed a case","d":"Leaving out a possibility in a case split."},
"off-by-one":{"name":"Off-by-one in a count or sum","d":"Starting or stopping a count or sum one place early or late."},
"signed-area":{"name":"Took signed area as area","d":"Integrating straight through a region below the axis, so parts cancel."},
"endpoint-extreme":{"name":"Took a stationary point as the extreme without checking the endpoints","d":"The largest or smallest value can be at an end of the interval."},
"tangency":{"name":"Miscounted roots at a tangency","d":"Treating a repeated root or a point of tangency as two roots, or as none."},
"binomial-term":{"name":"Wrong term or coefficient in a binomial expansion","d":"Picking the wrong power, or leaving out the binomial coefficient or a sign."},
"series-terms":{"name":"Wrong number of terms in a series","d":"Using n where the series has n + 1 or n - 1 terms."},
"other-quantity":{"name":"Answered a different quantity","d":"Correct working that stops at, or finds, something other than what was asked."},
"from-examples":{"name":"Generalised from examples","d":"Assuming a pattern seen in a few cases continues."},
"transform-order":{"name":"Applied transformations in the wrong order","d":"Doing a stretch and a translation in the wrong order."},
"limits":{"name":"Used the wrong limits or bounds","d":"Wrong integration limits, a wrong end of an interval, or a bound that is never reached."},
"at-least-exactly":{"name":"Confused \"at least\" with \"exactly\"","d":"Counting 'exactly k' when the question asks for 'at least k', or the reverse."},
"one-to-one":{"name":"Assumed a function is one-to-one or monotonic","d":"Assuming each output comes from one input, or that a function only increases."},
"algebra-rule":{"name":"Misapplied an algebra rule","d":"Steps such as 1/a + 1/b = 1/(a + b), or forgetting to square or to divide by a leading coefficient."},
"forgot-dudx":{"name":"Forgot du/dx in a substitution","d":"Changing variable without the factor from du = k dx, so the integral is out by that factor."},
"figure-length":{"name":"Used the wrong length or quantity from the figure","d":"Taking a radius, side or height from the diagram that is not the one the formula needs."},
"false-symmetry":{"name":"Assumed symmetry or oddness that isn’t there","d":"Treating a function as odd, even or symmetric when only part of it is."},
"gave-up":{"name":"Chose “cannot be determined” too early","d":"Deciding the information is not enough before trying to combine what is given."}
};
